import{_ as t,o,c as a,a3 as n}from"./chunks/framework.B9qR_F1m.js";const p=JSON.parse('{"title":"Install, uninstall and rollback","description":"","frontmatter":{},"headers":[],"relativePath":"install-and-rollback.md","filePath":"install-and-rollback.md"}'),s={name:"install-and-rollback.md"};function r(i,e,d,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="install-uninstall-and-rollback" tabindex="-1">Install, uninstall and rollback <a class="header-anchor" href="#install-uninstall-and-rollback" aria-label="Permalink to &quot;Install, uninstall and rollback&quot;">​</a></h1><h2 id="the-rules-ripeat-keeps" tabindex="-1">The rules ripeat keeps <a class="header-anchor" href="#the-rules-ripeat-keeps" aria-label="Permalink to &quot;The rules ripeat keeps&quot;">​</a></h2><ol><li><strong>Never remove what it did not install.</strong> A tool whose <code>check</code> already succeeds is recorded as <em>pre-existing</em>. Uninstall and rollback only forget it, and install never changes it: if you asked for a version that differs from the one already there, ripeat says so and leaves it (<a href="./assess">Risk and <code>assess</code></a>).</li><li><strong>Journal before acting.</strong> Each step is written to <code>state.json</code> as <code>pending</code> before it runs, then <code>done</code> or <code>failed</code>. That is what lets a failed or crashed run be undone.</li><li><strong>Honest about what cannot be undone.</strong> Anything ripeat could not undo is listed.</li><li><strong>No OS protections are ever disabled.</strong></li></ol><h2 id="ripeat-install-tool-version" tabindex="-1"><code>ripeat install [tool[@version] ...]</code> <a class="header-anchor" href="#ripeat-install-tool-version" aria-label="Permalink to &quot;`ripeat install [tool[@version] ...]`&quot;">​</a></h2><ol start="0"><li><strong>A name with no recipe</strong> (at a keyboard, not with <code>--dry-run</code>): ripeat says so and asks <code>Look for &quot;opera&quot; and draft a recipe? [y/N]</code>. On yes it does what <code>ripeat add</code> does (<a href="./find-and-add">Install by name</a>): looks the name up, lets you pick when it is found in more than one place, shows the drafted recipe, and saves it when you agree. Then the install carries on from step 1 with the new recipe, which is kept for next time. Answer no, or find nothing, and nothing is installed. <code>--yes</code> never answers this question, because a recipe made from something found on the internet is for you to read first. With no terminal (a script, an AI assistant) or with <code>--dry-run</code>, ripeat does not offer: it fails with <code>no recipe named ...</code> and the <code>ripeat add</code> hint, as before. With several such names it asks once for all of them, then shows every draft before one question to save them (<a href="./find-and-add">Install by name</a>).</li><li>Resolves the list and its dependencies (<a href="./recipes">Recipes</a>), applies <code>ripeat.lock</code> if present (<a href="./lockfile">The lockfile</a>), and prints the plan: tool, method, <code>user</code> or <code>admin</code>, and why it is there.</li><li>Rates the plan&#39;s risk (<a href="./assess">Risk and <code>assess</code></a>); a HIGH-risk plan is not run unless you confirm or pass <code>--accept-risk</code>.</li><li><strong>Asks before it changes anything:</strong> <code>Install 3 tools as shown above? [y/N]</code>. Answer <code>y</code> to go ahead. <code>--yes</code> (or <code>-y</code>) answers for you. With no terminal to ask in (a script, an AI assistant) and no <code>--yes</code>, ripeat refuses and changes nothing. A plan with nothing to install asks nothing. Then it asks for admin rights once if any step needs them (<a href="./privileges">Admin rights</a>).</li><li>Runs the steps in dependency order. Tools already managed are skipped; tools already on the machine are recorded and left alone. A tool whose recipe is <code>manual</code> (<a href="./recipes">Recipes</a>) and that is not there is <strong>left for you</strong>: ripeat does not install it, carries on with the rest, and ends with a &quot;Left for you to install by hand&quot; list.</li><li>If a step makes the machine need a restart, the run pauses; see <a href="./reboots">Restarts and <code>resume</code></a>.</li><li>If a step fails, ripeat says why it probably failed (<a href="./failures">When something fails</a>) and the whole run is undone, newest step first, so the machine returns to how it was. <code>--no-rollback</code> turns this off; you can then run <code>ripeat rollback</code> yourself.</li></ol><p><code>ripeat plan</code> (or <code>--dry-run</code>) prints the plan and the commands that would run, and writes nothing.</p><h2 id="ripeat-uninstall-tool" tabindex="-1"><code>ripeat uninstall tool ...</code> <a class="header-anchor" href="#ripeat-uninstall-tool" aria-label="Permalink to &quot;`ripeat uninstall tool ...`&quot;">​</a></h2><ul><li>Shows what it will remove (and which tools it will only forget), then asks <code>Go ahead? [y/N]</code>; <code>--yes</code> answers for you, and with no terminal it refuses without it.</li><li>Refuses to remove a tool that another managed tool still requires, unless <code>--force</code>.</li><li>Removes in an order where dependents go before what they need.</li><li>A pre-existing tool is only forgotten, not removed.</li><li>Afterwards it names dependencies that were installed only for the removed tool and are no longer needed. It does not remove them for you.</li><li><code>remove</code> is an alias.</li></ul><h2 id="ripeat-rollback" tabindex="-1"><code>ripeat rollback</code> <a class="header-anchor" href="#ripeat-rollback" aria-label="Permalink to &quot;`ripeat rollback`&quot;">​</a></h2><p>Undoes the <strong>most recent</strong> run that is not already undone; run it again for older runs. It lists what it will undo and asks <code>Undo this run as shown above? [y/N]</code>; <code>--yes</code> answers for you, and with no terminal and no <code>--yes</code> it refuses. What &quot;undo&quot; means per kind of step:</p><table tabindex="0"><thead><tr><th>Step</th><th>Undone by</th></tr></thead><tbody><tr><td>install</td><td>uninstall (never for pre-existing tools)</td></tr><tr><td>uninstall</td><td>reinstall (at the recorded version, or the latest if it was unpinned). A tool that is already back is not reinstalled: only the record is restored, and winget&#39;s &quot;already installed, nothing to upgrade&quot; answer counts as done</td></tr><tr><td>upgrade</td><td><strong>not undone</strong>: the old version is not kept; rollback says so and leaves it</td></tr><tr><td>policy (users, groups)</td><td>removing what that run created (<a href="./policy">Users and groups</a>)</td></tr></tbody></table><p>Each <code>rollback</code> undoes <strong>one</strong> run. If older runs can still be undone, it says so (<code>An older run can still be undone (...)</code>), and running it again undoes the next one: undoing an <code>uninstall</code> run reinstalls the tool, so check what it lists before you answer. <code>ripeat history</code> lists the runs.</p><p>Rollback is best effort: one failure does not stop the rest, everything that could not be undone is listed, and the run stays rollbackable so it can be retried. A run that was interrupted or crashed is undone from its journal. <code>--dry-run</code> lists what would be undone.</p><h2 id="reading-the-state" tabindex="-1">Reading the state <a class="header-anchor" href="#reading-the-state" aria-label="Permalink to &quot;Reading the state&quot;">​</a></h2><ul><li><code>ripeat list</code>: each managed tool, its version (detected, else requested), method, and whether it was already there.</li><li><code>ripeat history</code>: the last 20 runs, with status (<code>in_progress</code>, <code>complete</code>, <code>failed</code>, <code>rolled_back</code>, <code>needs_reboot</code>).</li></ul><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>Rollback cannot restore data a tool wrote itself (config, volumes, caches).</li><li>Rollback removes what ripeat installed, not packages the system manager pulled in as dependencies (for example <code>apt</code> installs <code>git</code> with <code>npm</code>; <code>apt autoremove</code> cleans those). <code>pacman</code> removal is the exception: it also drops helper packages.</li><li>A reinstall during rollback fetches the recorded version, or the latest if the install was unpinned.</li><li>Only one ripeat command that writes state runs at a time. A second one fails immediately, naming <code>state.json.lock</code>; the lock is released automatically if ripeat crashes. Dry runs and read-only commands (<code>list</code>, <code>history</code>, <code>recipes</code>, <code>outdated</code>, <code>lock</code>) do not take it.</li></ul>',17)])])}const f=t(s,[["render",r]]);export{p as __pageData,f as default};
